-- Source admission is durable across isolates. Writer receipts never expire:
-- a crashed writer refuses export, while ordinary use can continue. A hosted
-- export lease expires so an abandoned client cannot hold the app in maintenance.
CREATE TABLE dial_portability_admission (
 id TEXT PRIMARY KEY,
 kind TEXT NOT NULL CHECK (kind IN ('writer','export')),
 expires_at INTEGER,
 CHECK ((kind='writer' AND expires_at IS NULL) OR (kind='export' AND expires_at IS NOT NULL))
);
CREATE UNIQUE INDEX dial_portability_one_export ON dial_portability_admission(kind) WHERE kind='export';

-- Base accounts/schema/provider-control.sql: local dependency setup completion.
-- Existing owners start complete; a future first-owner bootstrap starts pending.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup)
 SELECT 1,0,0,0 WHERE EXISTS(SELECT 1 FROM oa_bootstrap) ON CONFLICT DO NOTHING;
CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

-- import-kit d1PreparationStepsSchema: control rows for preparations made across
-- requests (prepareD1ImportSteps). Erasure, cancellation and header retirement read it.
CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;

