CREATE TABLE poll_candidates (
 id TEXT PRIMARY KEY, poll_id TEXT NOT NULL REFERENCES meeting_polls(id) ON DELETE CASCADE,
 start_at TEXT NOT NULL, end_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(poll_id,start_at)
);
CREATE TABLE poll_participants (
 id TEXT PRIMARY KEY, poll_id TEXT NOT NULL REFERENCES meeting_polls(id) ON DELETE CASCADE,
 name TEXT NOT NULL, email TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(poll_id,email)
);
CREATE TABLE poll_vote_tokens (
 participant_id TEXT PRIMARY KEY REFERENCES poll_participants(id) ON DELETE CASCADE,
 token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE poll_votes (
 participant_id TEXT NOT NULL REFERENCES poll_participants(id) ON DELETE CASCADE,
 candidate_id TEXT NOT NULL REFERENCES poll_candidates(id) ON DELETE CASCADE,
 choice TEXT NOT NULL CHECK(choice IN('yes','if_needed','no')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 PRIMARY KEY(participant_id,candidate_id)
);
CREATE TRIGGER poll_participant_erasure_insert BEFORE INSERT ON poll_participants
WHEN EXISTS(SELECT 1 FROM person_erasure_locks WHERE email=NEW.email)
BEGIN SELECT RAISE(ABORT,'person_erasure_pending'); END;
CREATE TRIGGER poll_participant_erasure_update BEFORE UPDATE ON poll_participants
WHEN EXISTS(SELECT 1 FROM person_erasure_locks WHERE email=NEW.email)
BEGIN SELECT RAISE(ABORT,'person_erasure_pending'); END;
CREATE TRIGGER poll_vote_erasure_insert BEFORE INSERT ON poll_votes
WHEN EXISTS(SELECT 1 FROM poll_participants p JOIN person_erasure_locks l ON l.email=p.email WHERE p.id=NEW.participant_id)
BEGIN SELECT RAISE(ABORT,'person_erasure_pending'); END;

CREATE TABLE payment_processor_facts (
 id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
 account_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('charge','refund','fee','dispute','payout')),
 processor_ref TEXT NOT NULL, source_ref TEXT NOT NULL, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'usd' CHECK(currency GLOB '[a-z][a-z][a-z]'),
 status TEXT NOT NULL, disagreement INTEGER NOT NULL DEFAULT 0, resolved_at TEXT, resolved_by TEXT, event_created INTEGER NOT NULL,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(account_id,kind,processor_ref,booking_id)
);
CREATE INDEX payment_processor_facts_booking ON payment_processor_facts(booking_id);
CREATE TABLE accounting_connections (
 id TEXT PRIMARY KEY, realm_id TEXT NOT NULL, status TEXT NOT NULL,
 access_token_ciphertext TEXT, refresh_token_ciphertext TEXT, expires_at TEXT,
 income_account_id TEXT, item_id TEXT, reason TEXT, refresh_started_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE accounting_oauth_states (
 id TEXT PRIMARY KEY, session_id TEXT NOT NULL, operator_id TEXT NOT NULL,
 expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL
);
CREATE TABLE accounting_exports (
 id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
 connection_id TEXT NOT NULL, payment_ref TEXT NOT NULL, amount_cents INTEGER NOT NULL,
 request_id TEXT NOT NULL UNIQUE, document_ref TEXT NOT NULL, payload_json TEXT NOT NULL, receipt_id TEXT, state TEXT NOT NULL,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(connection_id,payment_ref)
);

CREATE TABLE workspace_notice_destinations (
 id TEXT PRIMARY KEY CHECK(id IN ('slack','teams')), generation INTEGER NOT NULL DEFAULT 1,
 status TEXT NOT NULL CHECK(status IN ('connected','failed','disconnected','needs_reconnect')),
 credential_ciphertext TEXT, target TEXT NOT NULL, external_key TEXT NOT NULL,
 masked_tail TEXT NOT NULL, reason TEXT, cooldown_until TEXT, active_delivery_id TEXT,
 alerted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE notice_oauth_states (
 id TEXT PRIMARY KEY, session_id TEXT NOT NULL, operator_id TEXT NOT NULL,
 mode TEXT NOT NULL CHECK(mode IN ('channel','dm')), target TEXT NOT NULL,
 expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL
);
CREATE TABLE workspace_notice_deliveries (
 id TEXT PRIMARY KEY, destination_id TEXT NOT NULL REFERENCES workspace_notice_destinations(id),
 generation INTEGER NOT NULL, account_id TEXT NOT NULL, channel_id TEXT NOT NULL, booking_id TEXT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
 occurrence_id TEXT NOT NULL REFERENCES booking_occurrences(id) ON DELETE CASCADE,
 event_kind TEXT NOT NULL CHECK(event_kind IN ('created','rescheduled','cancelled')),
 idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL CHECK(state IN ('pending','invoking','succeeded','failed','outcome_unknown')),
 attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, first_attempt_at TEXT,
 provider_ref TEXT, reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX workspace_notice_due ON workspace_notice_deliveries(state,next_attempt_at);
CREATE TABLE notice_erasure_requests (
 id TEXT PRIMARY KEY, receipt_id TEXT NOT NULL REFERENCES person_erasure_receipts(id),
 provider TEXT NOT NULL CHECK(provider IN ('slack','teams')), source_delivery_id TEXT NOT NULL,
 account_id TEXT NOT NULL, channel_id TEXT NOT NULL, processor_ref TEXT,
 state TEXT NOT NULL CHECK(state IN ('pending','completed','failed')), reason TEXT,
 requested INTEGER NOT NULL DEFAULT 0, archive_historical INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(receipt_id,source_delivery_id)
);

CREATE TABLE payment_products (
 id TEXT PRIMARY KEY, event_type_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('package','membership','gift')), name TEXT NOT NULL,
 sessions INTEGER NOT NULL CHECK(sessions BETWEEN 1 AND 1000),
 amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 50 AND 99999999),
 validity_days INTEGER NOT NULL CHECK(validity_days BETWEEN 1 AND 3660),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE payment_entitlements (
 id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES payment_products(id),
 event_type_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('package','membership','gift')),
 sessions INTEGER NOT NULL, balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0), amount_cents INTEGER NOT NULL,
 purchaser_email_folded TEXT NOT NULL, code_hash TEXT NOT NULL UNIQUE, purchase_key TEXT NOT NULL UNIQUE,
 checkout_session_id TEXT UNIQUE, account_id TEXT NOT NULL, subscription_id TEXT UNIQUE,
 state TEXT NOT NULL CHECK(state IN ('pending','active','past_due','erased')),
 expires_at TEXT NOT NULL, period_start TEXT, period_end TEXT, last_event_at INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX payment_entitlement_purchaser ON payment_entitlements(purchaser_email_folded,event_type_id);
CREATE TABLE payment_redemptions (
 id TEXT PRIMARY KEY, entitlement_id TEXT NOT NULL REFERENCES payment_entitlements(id),
 booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE CASCADE,
 units INTEGER NOT NULL CHECK(units>0), free_window_hours INTEGER, restored_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE payment_entitlement_events (
 id TEXT PRIMARY KEY, entitlement_id TEXT NOT NULL REFERENCES payment_entitlements(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL
);
CREATE TRIGGER payment_entitlement_insert_fence BEFORE INSERT ON payment_entitlements
WHEN EXISTS(SELECT 1 FROM person_erasure_locks WHERE email=NEW.purchaser_email_folded)
BEGIN SELECT RAISE(ABORT,'person_erasure_in_progress'); END;
CREATE TRIGGER payment_entitlement_identity_fence BEFORE UPDATE OF purchaser_email_folded ON payment_entitlements
WHEN EXISTS(SELECT 1 FROM person_erasure_locks WHERE email=NEW.purchaser_email_folded)
BEGIN SELECT RAISE(ABORT,'person_erasure_in_progress'); END;

-- Native roles can be represented before the full workspace role UI ships.
-- Public invitations remain equal owners; private doors deny lower roles until
-- their own scoped permission is implemented. Move-in admits owner and admin.
-- Existing owners retain equal authority while scoped role management is absent.
DROP TRIGGER dial_equal_operator_role_insert;
DROP TRIGGER dial_equal_operator_role_update;
CREATE TRIGGER dial_equal_operator_role_update BEFORE UPDATE OF role ON oa_operators
 WHEN OLD.role = 'owner' AND NEW.role != 'owner'
 BEGIN SELECT RAISE(ABORT,'dial_equal_operators'); END;

CREATE TABLE teams (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, host_id TEXT NOT NULL REFERENCES host_profiles(id),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE team_event_types (
 team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
 event_type_id TEXT NOT NULL REFERENCES event_types(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 PRIMARY KEY(team_id,event_type_id)
);
CREATE TABLE routing_forms (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, host_id TEXT NOT NULL REFERENCES host_profiles(id),
 config_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE routing_submissions (
 id TEXT PRIMARY KEY, form_id TEXT NOT NULL REFERENCES routing_forms(id),
 event_type_id TEXT REFERENCES event_types(id), team_id TEXT REFERENCES teams(id),
 host_id TEXT NOT NULL REFERENCES host_profiles(id), rule_id TEXT,
 state TEXT NOT NULL CHECK(state IN ('matched','disqualified')),
 result_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX routing_submissions_form_idx ON routing_submissions(form_id,created_at);
CREATE TABLE routing_capabilities (
 id TEXT PRIMARY KEY, form_id TEXT NOT NULL REFERENCES routing_forms(id) ON DELETE CASCADE,
 nonce_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, consumed_at TEXT,
 submission_id TEXT REFERENCES routing_submissions(id), payload_hash TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX routing_capabilities_expiry_idx ON routing_capabilities(expires_at);

-- The relationships are retired atomically with their owning records. Older
-- schemas keep their deletion path until these webhook tables are installed.
CREATE TRIGGER webhook_event_type_delete BEFORE DELETE ON event_types BEGIN
 UPDATE routing_submissions SET event_type_id=NULL,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE event_type_id=OLD.id;
 DELETE FROM webhook_deliveries WHERE json_extract(body_json,'$.data.eventTypeId')=OLD.id;
END;

-- Vote facts identify their poll, without repeating its event-type identifier.
CREATE TRIGGER webhook_poll_delete BEFORE DELETE ON meeting_polls BEGIN
 DELETE FROM webhook_deliveries WHERE json_extract(body_json,'$.data.pollId')=OLD.id;
END;

